            if (k < R + C && pattern[j + k] != 'A')
                dp[j][k + 1] += dp[j][k];
        }

    int M = N - C;
    vector<vector<ll>> asums2(R + C + 1);
    for (int al = R - 1; al <= R + C; al++)
    {
        search(M, N, al, R + C - al, req_mask, excl_mask, 0, asums2[al]);
        sort(RA(asums2[al]), greater<ll>());
    }
    ll total_score = 0;
    for (int a = R - 1; a <= R + C; a++)
        for (int b = R; b <= R + C; b++)
        {
            if (a > R - 1 && b > R)
                continue;
            if (dp[a][b] == 0)
                continue;
            int L = a + b;
            for (int l = 0; l <= M - L; l++)
            {
                int r = R + C - a - l;
                if (r > N - M || r < 0)
                    continue;
                vector<ll> sums1;
                search(L, M, a, l, req_mask, excl_mask, 0, sums1);
                auto &sums2 = asums2[a + l];
                sort(RA(sums1));
                int p = 0, q = 0;
                int p2 = 0, q2 = 0;
                while (p < (int)sums1.size() && q < (int)sums2.size())
