import java.util.*;
import java.io.*;

public class Main {
    static int R, C;
    static List<List<Long>> comb = new ArrayList<>();

    public static void main(String[] args) throws IOException {
        configureSystem(args);
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        R = Integer.parseInt(st.nextToken());
        C = Integer.parseInt(st.nextToken());
        String pattern = br.readLine();

        int N = 2 * (R + C);
        for (int i = 0; i <= N; i++) {
            List<Long> row = new ArrayList<>(Collections.nCopies(i + 1, 0L));
            row.set(0, 1L);
            row.set(i, 1L);
            comb.add(row);
        }
        for (int i = 0; i <= N; i++) {
            for (int j = 1; j < i; j++) {
                long val = comb.get(i - 1).get(j - 1) + comb.get(i - 1).get(j);
                comb.get(i).set(j, val);
            }
        }

        Pair<Long, Long> opt = evaluate("?".repeat(N));
        Pair<Long, Long> score = evaluate(pattern);
        if (score.first.equals(opt.first))
            System.out.println(score.second);
        else
            System.out.println(0);
    }

    static void configureSystem(String[] args) {
        // No equivalent in Java for system resource limits or input/output redirection
        // as in C++. This method is left intentionally blank.
    }

    static long getComb(int n, int r) {
        if (n < 0 || n >= comb.size() || r < 0 || r >= comb.get(n).size())
            return 0;
        return comb.get(n).get(r);
    }

    static long makeMask(int x) {
        return 1L << x;
    }

    static Pair<Long, Long> evaluate(String pattern) {
        int N = pattern.length();
        long baseSum = 0;
        for (int i = 0; i < R + C; i++) {
            baseSum += getComb(i, R - 1) * getComb(N - i - 1, R);
        }
        long minDiff = Long.MAX_VALUE;
        long targetValue = 2 * baseSum - getComb(N, 2 * R);

        long reqMask = 0, exclMask = 0;
        for (int i = 0; i < N; i++) {
            if (pattern.charAt(i) == 'A')
                reqMask |= makeMask(i);
            else if (pattern.charAt(i) == 'B')
                exclMask |= makeMask(i);
        }

        long[][] dp = new long[R + C + 1][R + C + 1];
        for (long[] row : dp)
            Arrays.fill(row, 0);
        dp[0][0] = 1;

        for (int j = 0; j <= R + C; j++) {
            for (int k = 0; k <= R + C; k++) {
                if (j >= R - 1 && k >= R)
                    break;
                if (j < R + C && pattern.charAt(j + k) != 'B')
                    dp[j + 1][k] += dp[j][k];
                if (k < R + C && pattern.charAt(j + k) != 'A')
                    dp[j][k + 1] += dp[j][k];
            }
        }

        int M = N - C;
        List<List<Long>> asums2 = new ArrayList<>();
        for (int i = 0; i <= R + C; i++) {
            asums2.add(new ArrayList<>());
        }

        for (int al = R - 1; al <= R + C; al++) {
            List<Long> sumsList = new ArrayList<>();
            search(M, N, al, R + C - al, reqMask, exclMask, 0L, sumsList);
            sumsList.sort(Collections.reverseOrder());
            asums2.set(al, sumsList);
        }

        long totalScore = 0;
        for (int a = R - 1; a <= R + C; a++) {
            for (int b = R; b <= R + C; b++) {
                if (a > R - 1 && b > R)
                    continue;
                if (dp[a][b] == 0)
                    continue;
                int L = a + b;
                for (int l = 0; l <= M - L; l++) {
                    int r = R + C - a - l;
                    if (r > N - M || r < 0)
                        continue;
                    List<Long> sums1 = new ArrayList<>();
                    search(L, M, a, l, reqMask, exclMask, 0L, sums1);
                    List<Long> sums2 = asums2.get(a + l);
                    Collections.sort(sums1);
                    int p = 0, q = 0;
                    int p2 = 0, q2 = 0;
                    while (p < sums1.size() && q < sums2.size()) {
                        while (p2 < sums1.size() && sums1.get(p2).equals(sums1.get(p)))
                            p2++;
                        while (q2 < sums2.size() && sums2.get(q2).equals(sums2.get(q)))
                            q2++;
                        long total = 2 * (sums1.get(p) + sums2.get(q));
                        long diff = Math.abs(total - targetValue);
                        if (diff < minDiff) {
                            minDiff = diff;
                            totalScore = 0;
                        }
                        if (diff == minDiff)
                            totalScore += (long)(p2 - p) * (q2 - q) * dp[a][b];
                        if (total > targetValue)
                            q = q2;
                        else
                            p = p2;
                    }
                }
            }
        }
        return new Pair<>(minDiff, totalScore);
    }

    static void search(int L, int N, int a, int na, long req, long excl, long cur, List<Long> sums) {
        if (na > N - L)
            return;
        if (L == N) {
            sums.add(cur);
            return;
        }
        long mask = makeMask(L);
        if ((req & mask) == 0)
            search(L + 1, N, a, na, req, excl, cur, sums);
        if (na > 0 && (excl & mask) == 0) {
            long nextVal = cur + getComb(a, R - 1) * getComb(L - a, R);
            search(L + 1, N, a + 1, na - 1, req, excl, nextVal, sums);
        }
    }

    static class Pair<F, S> {
        public final F first;
        public final S second;

        public Pair(F first, S second) {
            this.first = first;
            this.second = second;
        }
    }
}
